import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import BackButton from './BackButton';

export const revalidate = 300;
export const dynamicParams = true;

interface Post {
  id: number;
  title: string;
  body: string;
}

interface Comment {
  id: number;
  name: string;
  body: string;
  email: string;
}

interface PageProps {
  params: Promise<{ id: string }>;
}

export async function generateStaticParams() {
  const posts: Post[] = await fetch('https://jsonplaceholder.typicode.com/posts').then(res => res.json());
  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }));
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const resolvedParams = await params;
  try {
    const postRes = await fetch(`https://jsonplaceholder.typicode.com/posts/${resolvedParams.id}`);
    if (!postRes.ok) return {};
    const post: Post = await postRes.json();
    if (!post || !post.id) return {};

    return {
      title: post.title,
      description: post.body.substring(0, 160),
      openGraph: {
        title: post.title,
        description: post.body.substring(0, 160),
      },
    };
  } catch {
    return {};
  }
}

export default async function BlogPost({ params }: PageProps) {
  const resolvedParams = await params;

  try {
    const [postRes, commentsRes] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${resolvedParams.id}`),
      fetch(`https://jsonplaceholder.typicode.com/posts/${resolvedParams.id}/comments`)
    ]);

    if (!postRes.ok) {
      return notFound();
    }

    const post: Post = await postRes.json();
    if (!post || !post.id) {
      return notFound();
    }

    const comments: Comment[] = await commentsRes.json();

    return (
      <article>
        <BackButton />

        <h1>{post.title}</h1>
        <p>{post.body}</p>

        <h2>Comments ({comments.length})</h2>
        <div className="comments">
          {comments.map((comment) => (
            <div key={comment.id} className="comment">
              <h3>{comment.name}</h3>
              <p>{comment.body}</p>
              <small>By: {comment.email}</small>
            </div>
          ))}
        </div>
      </article>
    );
  } catch (error) {
    notFound();
  }
}

